function render({resetScroll=false}={}){
  const s=state(),c=$('#content');
  if(!s||!c||s.view!=='rewards'||!core())return;
  const refreshed=core().refreshState(s);
  if(refreshed!==s){save(refreshed);return}
  const pos=resetScroll?0:c.scrollTop;
  painting=true;
  c.dataset.flytOwner='rewards-ui';
  c.innerHTML=`<div class="goalsPage"><h1 class="title">Belønning</h1><p class="goalsIntro">Motiver hverandre litt ekstra.</p>${mainView(s)}<section class="goalSection rewardHistorySection"><button class="goalHistoryLink" data-goal-history>Historikk <span aria-hidden="true">›</span></button></section></div>`;
  document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('on',b.dataset.view==='rewards'));
  painting=false;
  c.scrollTop=pos;
  requestAnimationFrame(()=>c.scrollTop=pos);
}
