function temptationInput(s){const d=temptationDraft,type=d.conditionType==='points'?'points_new':d.conditionType==='task'?'task_once':'manual',target=type==='points_new'?Math.max(10,Number(d.points)||10):1,rewardTitle=temptationReward();return{kind:'challenge',title:type==='manual'?d.manual.trim():'',metric:{type,target,taskId:type==='task_once'?d.taskId:''},deadline:d.deadline,note:'',targetUser:partner(s),reward:{title:rewardTitle,type:'challenge',cost:0,direct:true,model:'earned',secret:!!d.secret,category:Object.entries(core().REWARD_LIBRARY).find(([,items])=>items.includes(rewardTitle))?.[0]||'Eget forslag'}}}
function temptationRow(label,attrs='',on=false,sub=''){return`<button type="button" class="temptationRow ${on?'on':''}" ${attrs}><span><strong>${esc(label)}</strong>${sub?`<small>${esc(sub)}</small>`:''}</span><i aria-hidden="true">${on?'✓':'›'}</i></button>`}
function temptationHeader(){const d=temptationDraft;return`<header class="temptationHead"><button type="button" class="temptationBack" ${d.step>1?'data-temptation-back':'data-temptation-close'} aria-label="${d.step>1?'Tilbake':'Lukk'}">${d.step>1?'‹':'×'}</button><div><span class="ey">FRISTELSE</span><small>Steg ${d.step} av 4</small></div><button type="button" class="temptationClose" data-temptation-close aria-label="Lukk">×</button></header><div class="temptationProgress"><i style="width:${d.step*25}%"></i></div>`}
function temptationStepOne(s){const rewards=['Massasje','Sovemorgen','Datekveld','En kveld sammen','Du velger ❤️'],selected=temptationReward(),quickSelected=rewards.includes(selected),catalogSelected=!!selected&&!quickSelected,catalogLabel=catalogSelected?selected:'Se alle fristelser',catalogSub=catalogSelected?'Trykk for å endre':'Flere valg og eget forslag';return`<div class="temptationScreen"><h2>Hva vil du friste ${esc(partner(s))} med?</h2><div class="temptationRows">${rewards.map(x=>temptationRow(x,`data-temptation-reward="${esc(x)}"`,selected===x)).join('')}</div>${temptationRow(catalogLabel,'data-temptation-catalog',catalogSelected,catalogSub)}</div>`}


function temptationTypeChoice(selected=''){
  const items=[['task','Gjøremål'],['points','Tjen poeng'],['manual','Skriv selv']];
  return `<div class="temptationConditionSegment" role="tablist" aria-label="Velg type vilkår">${items.map(([type,label])=>`<button type="button" role="tab" aria-selected="${selected===type}" class="${selected===type?'on':''}" data-temptation-type="${type}">${esc(label)}</button>`).join('')}</div>`;
}

function temptationStepTwo(s){
  const d=temptationDraft;
  let body='';
  if(d.conditionType==='task'){
    const quickTasks=temptationTasks(s),chosen=temptationTask(s),chosenIsQuick=quickTasks.some(t=>String(t.id)===String(d.taskId));
    const selected=chosen&&!chosenIsQuick?`<div class="temptationSelected"><span class="ey">VALGT GJØREMÅL</span><strong>${esc(chosen.name)}</strong></div>`:'';
    const quick=quickTasks.map(t=>temptationRow(t.name,`data-temptation-task="${esc(t.id)}"`,String(t.id)===String(d.taskId))).join('');
    body=`<section class="temptationConditionBody temptationTaskSection" aria-labelledby="temptationTaskHeading"><div class="temptationSectionHead"><span class="ey" id="temptationTaskHeading">VELG ET GJØREMÅL</span><p>Velg oppgaven som skal fullføres.</p></div>${selected}<div class="temptationRows">${quick}</div><div class="temptationRows temptationMoreRows">${temptationRow('Se alle gjøremål','data-temptation-task-catalog',false,'Flere valg i gjøremålsbiblioteket')}</div></section>`;
  }else if(d.conditionType==='points'){
    body=`<section class="temptationConditionBody" aria-labelledby="temptationPointsHeading"><div class="temptationSectionHead"><span class="ey" id="temptationPointsHeading">VELG POENGMÅL</span><p>Kun nye poeng etter aksept teller.</p></div><div class="temptationQuestion"><span class="ey">HVOR MANGE NYE POENG?</span><button type="button" class="pointSelect" data-temptation-point-open><strong data-point-summary>${d.points} nye poeng</strong><i aria-hidden="true">›</i><input name="temptationPoints" type="hidden" value="${d.points}"></button></div></section>`;
  }else if(d.conditionType==='manual'){
    body=`<section class="temptationConditionBody" aria-labelledby="temptationManualHeading"><div class="temptationSectionHead"><span class="ey" id="temptationManualHeading">SKRIV VILKÅRET</span><p>Formuler kort hva som skal til.</p></div><label class="temptationText"><span>Eget gjøremål eller vilkår</span><textarea name="temptationManual" maxlength="140" placeholder="Skriv hva som skal til …">${esc(d.manual)}</textarea></label></section>`;
  }
  return `<div class="temptationScreen"><div class="temptationMini">Fristelse: <strong>${esc(temptationReward())}</strong></div><h2>Hva skal til?</h2><p class="temptationLead">Velg én betingelse.</p>${temptationTypeChoice(d.conditionType)}${body}</div>`;
}
function temptationStepThree(s){const d=temptationDraft;return`<div class="temptationScreen"><div class="temptationMini"><strong>${esc(temptationReward())} ❤️</strong><span>${esc(temptationCondition(s))}</span></div><h2>Når skal det gjelde?</h2><div class="temptationRows">${temptationRow('I kveld','data-temptation-deadline="today"',d.deadline===dateKeyLocal())}${temptationRow('I morgen','data-temptation-deadline="tomorrow"',localDeadline(d.deadline)===dateKeyLocal(new Date(Date.now()+86400000)))}${temptationRow('Denne uka','data-temptation-deadline="week"',localDeadline(d.deadline)===localDeadline(core().endOfWeek()))}${temptationRow('Velg annen tid','data-temptation-deadline-custom',false,'Dato og klokkeslett')}</div>${d.deadline?`<div class="temptationDeadline"><span>Valgt frist</span><strong>${esc(deadlineLabel(d.deadline))}</strong></div>`:''}</div>`}
function temptationStepFour(s){const d=temptationDraft;return`<div class="temptationScreen"><h2>Slik blir fristelsen</h2><dl class="temptationReview"><div><dt>Fristelse</dt><dd>${esc(temptationReward())}</dd></div><div><dt>Vilkår</dt><dd>${esc(temptationCondition(s))}</dd></div><div><dt>Frist</dt><dd>${esc(deadlineLabel(d.deadline))}</dd></div></dl><label class="temptationSecret"><span><strong>Hemmelig belønning 🔒</strong><small>Partneren ser ikke fristelsen før den avsløres.</small></span><input type="checkbox" name="temptationSecret" ${d.secret?'checked':''}></label><div class="temptationPreview">${esc(temptationPreview(s))}</div></div>`}
function syncTemptationForm(form){if(!form||!temptationDraft)return;const points=form.elements.temptationPoints,manual=form.elements.temptationManual;temptationDraft={...temptationDraft,points:points?Math.max(10,Number(points.value)||10):temptationDraft.points,manual:manual?manual.value:temptationDraft.manual,secret:!!form.elements.temptationSecret?.checked}}
function closeTemptation(){temptationDraft=null;$('#goalSheetLayer')?.remove();$('#fristelseCatalogLayer')?.remove();$('#fristelseTaskCatalogLayer')?.remove();$('#pointPickerLayer')?.remove();$('#deadlinePickerLayer')?.remove()}
function backTemptation(form){if(!temptationDraft||temptationDraft.step<=1)return;syncTemptationForm(form);temptationDraft.step=Math.max(1,temptationDraft.step-1);renderTemptation()}
function renderTemptation(){const s=state(),d=temptationDraft;if(!s||!d)return;let layer=$('#goalSheetLayer');if(!layer){layer=document.createElement('div');layer.id='goalSheetLayer';document.body.appendChild(layer)}const previousShell=layer.querySelector('.temptationShell'),previousBody=layer.querySelector('.temptationBody'),sameStep=Number(previousShell?.dataset.flowStep)===Number(d.step),previousScroll=sameStep?Math.max(0,Number(previousBody?.scrollTop)||0):0;layer.className='goalSheetLayer temptationFlowLayer';const content=d.step===1?temptationStepOne(s):d.step===2?temptationStepTwo(s):d.step===3?temptationStepThree(s):temptationStepFour(s),cta=d.step===4?'Send fristelse ❤️':'Neste';layer.innerHTML=`<section class="temptationShell" data-flow-step="${d.step}" role="dialog" aria-modal="true">${temptationHeader()}<form id="temptationFlowForm"><main class="temptationBody">${content}</main><footer class="temptationFooter"><button class="goalPrimary" type="${d.step===4?'submit':'button'}" ${d.step<4?'data-temptation-next':''} ${temptationReady()?'':'disabled'}>${cta}</button></footer></form></section>`;const form=layer.querySelector('#temptationFlowForm');if(sameStep)restoreFlowScroll(layer.querySelector('.temptationBody'),previousScroll);layer.onclick=temptationClick;layer.onchange=temptationChange;layer.oninput=temptationInputEvent;form.onsubmit=submitTemptation;window.FlytEdgeSwipeBack?.bind(layer.querySelector('.temptationShell'),{canGoBack:()=>temptationDraft?.step>1,onBack:()=>backTemptation(form)})}
function openFristelse(){const s=state();if(!s)return;temptationDraft={step:1,reward:'',rewardCustom:'',conditionType:'',taskId:'',points:60,manual:'',deadline:'',secret:false};renderTemptation()}
function temptationClick(e){const layer=e.currentTarget,form=layer.querySelector('#temptationFlowForm');if(e.target===layer||e.target.closest('[data-temptation-close]')){e.preventDefault();e.stopPropagation();closeTemptation();return}const reward=e.target.closest('[data-temptation-reward]');if(reward){e.preventDefault();e.stopPropagation();temptationDraft.reward=reward.dataset.temptationReward;temptationDraft.rewardCustom='';renderTemptation();return}if(e.target.closest('[data-temptation-catalog]')){e.preventDefault();e.stopPropagation();openTemptationCatalog();return}if(e.target.closest('[data-temptation-task-catalog]')){e.preventDefault();e.stopPropagation();openTemptationTaskCatalog();return}if(e.target.closest('[data-temptation-custom-condition]')){e.preventDefault();e.stopPropagation();temptationDraft.conditionType='manual';temptationDraft.taskId='';temptationDraft.points=60;renderTemptation();requestAnimationFrame(()=>layer.querySelector('[name="temptationManual"]')?.focus({preventScroll:true}));return}const type=e.target.closest('[data-temptation-type]');if(type){e.preventDefault();e.stopPropagation();temptationDraft.conditionType=type.dataset.temptationType;if(temptationDraft.conditionType==='task'){temptationDraft.points=60;temptationDraft.manual=''}else if(temptationDraft.conditionType==='points'){temptationDraft.taskId='';temptationDraft.manual=''}else{temptationDraft.taskId='';temptationDraft.points=60}renderTemptation();return}if(e.target.closest('[data-temptation-type-back]')){e.preventDefault();e.stopPropagation();syncTemptationForm(form);temptationDraft.conditionType='';renderTemptation();return}const task=e.target.closest('[data-temptation-task]');if(task){e.preventDefault();e.stopPropagation();temptationDraft.taskId=task.dataset.temptationTask;renderTemptation();return}const points=e.target.closest('[data-temptation-point-open]');if(points){e.preventDefault();e.stopPropagation();openPointPicker(form,'temptationPoints','nye poeng',{min:10,max:5000,step:10,title:'Hvor mange nye poeng?',allowCustom:true});return}const deadline=e.target.closest('[data-temptation-deadline]');if(deadline){e.preventDefault();e.stopPropagation();temptationDraft.deadline=deadline.dataset.temptationDeadline==='today'?dateKeyLocal():deadline.dataset.temptationDeadline==='tomorrow'?dateKeyLocal(new Date(Date.now()+86400000)):core().endOfWeek();renderTemptation();return}if(e.target.closest('[data-temptation-deadline-custom]')){e.preventDefault();e.stopPropagation();let hidden=form.elements.deadline;if(!hidden){hidden=document.createElement('input');hidden.type='hidden';hidden.name='deadline';form.appendChild(hidden)}hidden.value=temptationDraft.deadline||dateKeyLocal();openDeadlinePicker(form);return}if(e.target.closest('[data-temptation-back]')){e.preventDefault();e.stopPropagation();syncTemptationForm(form);temptationDraft.step=Math.max(1,temptationDraft.step-1);renderTemptation();return}if(e.target.closest('[data-temptation-next]')){e.preventDefault();e.stopPropagation();syncTemptationForm(form);if(!temptationReady()){bridge()?.toast?.('Velg et alternativ før du fortsetter');return}temptationDraft.step=Math.min(4,temptationDraft.step+1);renderTemptation()}}
function temptationChange(e){const form=e.currentTarget.querySelector('#temptationFlowForm');if(e.target.name==='temptationSecret'){e.stopPropagation();syncTemptationForm(form);renderTemptation()}}
function temptationInputEvent(e){if(e.target.name==='temptationManual'){temptationDraft.manual=e.target.value;const button=e.currentTarget.querySelector('.temptationFooter .goalPrimary');if(button)button.disabled=!temptationReady()}}
function submitTemptation(e){e.preventDefault();e.stopPropagation();syncTemptationForm(e.currentTarget);if(!temptationReady())return;const s=state(),input=temptationInput(s);save(core().createGoal(s,input),'Fristelsen er sendt');closeTemptation();render()}
function openTemptationCatalog(){const layer=document.createElement('div'),selected=temptationReward(),flow=$('#goalSheetLayer .temptationShell'),restoreFlow=()=>flow?.setAttribute('aria-modal','true');flow?.setAttribute('aria-modal','false');layer.id='fristelseCatalogLayer';layer.className='fristelseCatalogLayer';layer.innerHTML=`<section class="fristelseCatalog" role="dialog" aria-modal="true"><div class="deadlineHandle"></div><div class="deadlinePickerHead"><h3>Velg fristelse</h3><button type="button" data-temptation-catalog-close>Lukk</button></div><div class="fristelseCatalogScroll">${Object.entries(core().REWARD_LIBRARY).map(([cat,items])=>`<section><span class="ey">${esc(cat)}</span>${items.filter(x=>x!=='Eget forslag').map(x=>`<button type="button" data-temptation-catalog-reward="${esc(x)}">${esc(x)}<b>${x===selected?'✓':''}</b></button>`).join('')}</section>`).join('')}<label class="fristelseCustom">Eget forslag<input data-temptation-custom maxlength="100"><button type="button" data-temptation-custom-save>Bruk eget forslag</button></label></div></section>`;layer.onclick=e=>{e.stopPropagation();if(e.target===layer||e.target.closest('[data-temptation-catalog-close]')){restoreFlow();layer.remove();return}const reward=e.target.closest('[data-temptation-catalog-reward]');if(reward){temptationDraft.reward=reward.dataset.temptationCatalogReward;temptationDraft.rewardCustom='';restoreFlow();layer.remove();renderTemptation();return}if(e.target.closest('[data-temptation-custom-save]')){const value=layer.querySelector('[data-temptation-custom]').value.trim();if(!value){bridge()?.toast?.('Skriv inn en fristelse');return}temptationDraft.reward='';temptationDraft.rewardCustom=value;restoreFlow();layer.remove();renderTemptation()}};document.body.appendChild(layer)}
function openTemptationTaskCatalog(){const layer=document.createElement('div'),selected=String(temptationDraft?.taskId||''),flow=$('#goalSheetLayer .temptationShell'),restoreFlow=()=>flow?.setAttribute('aria-modal','true');flow?.setAttribute('aria-modal','false');layer.id='fristelseTaskCatalogLayer';layer.className='fristelseCatalogLayer';layer.innerHTML=`<section class="fristelseCatalog" role="dialog" aria-modal="true"><div class="deadlineHandle"></div><div class="deadlinePickerHead"><h3>Velg gjøremål</h3><button type="button" data-temptation-task-catalog-close>Lukk</button></div><div class="fristelseCatalogScroll">${taskGroups(state()).map(group=>`<section><span class="ey">${esc(group.category)}</span>${group.tasks.map(task=>`<button type="button" data-temptation-catalog-task="${esc(task.id)}">${esc(task.name)}<b>${String(task.id)===selected?'✓':''}</b></button>`).join('')}</section>`).join('')}</div></section>`;layer.onclick=e=>{e.stopPropagation();if(e.target===layer||e.target.closest('[data-temptation-task-catalog-close]')){restoreFlow();layer.remove();return}const task=e.target.closest('[data-temptation-catalog-task]');if(task){temptationDraft.taskId=task.dataset.temptationCatalogTask;restoreFlow();layer.remove();renderTemptation()}};document.body.appendChild(layer)}

let goalDraft=null;
function goalTypes(){return core().METRICS.filter(item=>['points_new','task_specific','manual'].includes(item.type))}
function goalMetric(){return goalDraft?.metric||{type:'',target:0,taskId:''}}
function goalTitleDraft(s){const m=goalMetric();if(m.type==='points_new')return goalDraft?.kind==='shared'?`Tjen ${Math.max(1,Number(m.target)||1)} poeng sammen`:`Tjen ${Math.max(1,Number(m.target)||1)} poeng`;return core().goalTitle(s,m,goalDraft?.title||'')}
function goalReady(){const d=goalDraft,m=goalMetric();if(!d)return false;if(d.step===1)return['personal','shared'].includes(d.kind);if(d.step===2){if(!m.type)return false;if(m.type==='manual')return!!d.title?.trim();return !['task_specific','task_once'].includes(m.type)||!!m.taskId}return d.step!==3||!!d.deadline}
function goalHeader(){const d=goalDraft;return `<header class="temptationHead"><button type="button" class="temptationBack" ${d.step>1?'data-goalflow-back':'data-goalflow-close'} aria-label="${d.step>1?'Tilbake':'Lukk måloppsett'}">${d.step>1?'‹':'×'}</button><div><span class="ey">MÅL</span><small>Nytt mål · Steg ${d.step} av 4</small></div><button type="button" class="temptationClose" data-goalflow-close aria-label="Lukk måloppsett">×</button></header><div class="temptationProgress"><i style="width:${d.step*25}%"></i></div>`}
function goalRow(label,sub,attrs,on=false){return temptationRow(label,attrs,on,sub)}
const GOAL_TYPE_DEFAULTS={points_new:80,task_specific:1,manual:1};
function rememberGoalMetric(metric=goalMetric()){if(!goalDraft||!metric?.type)return;goalDraft.metricMemory={...(goalDraft.metricMemory||{}),[metric.type]:{...metric}}}
function selectGoalType(type){if(!goalDraft)return;rememberGoalMetric();const fallbackTask=(state()?.tasks||[]).find(item=>item.kind==='house')?.id||'';goalDraft.metric={type,target:GOAL_TYPE_DEFAULTS[type]||1,taskId:fallbackTask,...(goalDraft.metricMemory?.[type]||{})};goalDraft.metric.type=type}
function goalFields(s){const m=goalMetric(),target=Math.max(1,Number(m.target)||10),task=`<label class="goalFlowField"><span>Gjøremål</span>${challengeTaskPicker(s,m.taskId)}</label>`;if(!m.type)return'';if(m.type==='points_new')return `<div class="temptationQuestion"><span class="ey">HVOR MANGE POENG?</span>${pointStepper('goalPointTarget',target,'poeng',{title:'Velg poengmål'})}</div>`;if(m.type==='task_specific')return `<div class="goalFlowFields">${task}<div class="temptationQuestion"><span class="ey">ANTALL GANGER</span>${pointStepper('goalRepeatTarget',target,'ganger',{min:1,max:100,step:1,title:'Velg antall ganger',allowCustom:false})}</div></div>`;if(m.type==='manual')return `<label class="temptationText"><span>Hva er målet ditt?</span><textarea name="goalManualTitle" maxlength="140" placeholder="Skriv målet ditt …">${esc(goalDraft.title||'')}</textarea></label>`;return ''}
function goalTypeLabel(item,kind){if(item.type==='points_new')return kind==='shared'?'Tjen X poeng sammen':'Tjen X poeng';if(item.type==='task_specific')return'Gjør et bestemt gjøremål X ganger';return item.label}
function goalStep(s){const d=goalDraft,m=goalMetric();if(d.step===1)return `<div class="temptationScreen"><h2>Hvem gjelder målet?</h2><p class="temptationLead">Velg om dette er ditt mål eller noe dere gjør sammen.</p><div class="temptationRows">${goalRow('For meg','Et mål jeg jobber mot selv','data-goalflow-kind="personal"')}${goalRow('For oss','Et mål vi jobber mot sammen','data-goalflow-kind="shared"')}</div></div>`;if(d.step===2){const types=goalTypes();return `<div class="temptationScreen goalFlowStepTwo"><h2>Hva vil du oppnå?</h2><p class="temptationLead">Velg én tydelig måte å måle målet på.</p><div class="goalFlowTypeList">${types.map(item=>{const selected=m.type===item.type;return `${goalRow(goalTypeLabel(item,d.kind),'',`data-goalflow-type="${item.type}"`,selected)}${selected?`<div class="goalFlowInlineFields">${goalFields(s)}</div>`:''}`}).join('')}</div></div>`}if(d.step===3){const tomorrow=dateKeyLocal(new Date(Date.now()+86400000)),week=localDeadline(core().endOfWeek());return `<div class="temptationScreen"><div class="temptationMini"><span>${d.kind==='shared'?'For oss':'For meg'}</span><strong>${esc(goalTitleDraft(s))}</strong></div><h2>Når skal målet nås?</h2><div class="temptationRows">${goalRow('I morgen','','data-goalflow-deadline="tomorrow"',localDeadline(d.deadline)===tomorrow)}${goalRow('Denne uka','','data-goalflow-deadline="week"',localDeadline(d.deadline)===week)}${goalRow('Velg annen tid','Dato og klokkeslett','data-goalflow-deadline-other')}</div>${d.deadline?`<div class="temptationDeadline"><span>Valgt frist</span><strong>${esc(deadlineLabel(d.deadline))}</strong></div>`:''}<input type="hidden" name="deadline" value="${esc(d.deadline||'')}"></div>`}const reward=d.reward||'',custom=reward==='__custom__',rewardText=custom?d.rewardCustom:reward;return `<div class="temptationScreen"><h2>Gjør målet komplett</h2><dl class="temptationReview"><div><dt>Gjelder</dt><dd>${d.kind==='shared'?'For oss':'For meg'}</dd></div><div><dt>Mål</dt><dd>${esc(goalTitleDraft(s))}</dd></div><div><dt>Frist</dt><dd>${esc(deadlineLabel(d.deadline))}</dd></div></dl><label class="goalFlowReward"><span>Vil du knytte en belønning til målet? <em>(valgfritt)</em></span><select name="goalRewardPreset">${rewardOptions(custom?'':reward,{allowPartner:d.kind!=='personal'})}</select></label>${custom?`<label class="goalFlowReward"><span>Eget forslag</span><input name="goalRewardCustom" maxlength="100" value="${esc(d.rewardCustom||'')}" placeholder="Skriv belønningen"></label>`:''}<div class="temptationPreview">${esc(`${goalTitleDraft(s)}${rewardText?` · Belønning: ${rewardText}`:''}`)}</div></div>`}
function syncGoal(form){if(!form||!goalDraft)return;const m={...goalMetric()},num=name=>Number(form.elements[name]?.value),type=m.type;if(type==='points_new'&&Number.isFinite(num('goalPointTarget')))m.target=Math.max(10,num('goalPointTarget'));if(type==='task_specific'&&Number.isFinite(num('goalRepeatTarget')))m.target=Math.max(1,num('goalRepeatTarget'));if(type==='task_specific'&&form.elements.taskId?.value)m.taskId=form.elements.taskId.value;if(type==='manual'&&form.elements.goalManualTitle)goalDraft.title=form.elements.goalManualTitle.value;const deadline=form.elements.deadline?.value;if(deadline)goalDraft.deadline=deadline;const preset=form.elements.goalRewardPreset?.value;if(preset!==undefined){goalDraft.reward=preset;goalDraft.rewardCustom=form.elements.goalRewardCustom?.value||goalDraft.rewardCustom||''}goalDraft.metric=m;rememberGoalMetric(m)}
function closeGoalFlow(){goalDraft=null;$('#goalSheetLayer')?.remove();$('#pointPickerLayer')?.remove();$('#deadlinePickerLayer')?.remove()}
function renderGoalFlow(){const s=state(),d=goalDraft;if(!s||!d)return;let layer=$('#goalSheetLayer');if(!layer){layer=document.createElement('div');layer.id='goalSheetLayer';document.body.appendChild(layer)}const previousShell=layer.querySelector('.goalFlowShell'),previousBody=layer.querySelector('.temptationBody'),sameStep=Number(previousShell?.dataset.flowStep)===Number(d.step),previousScroll=sameStep?Math.max(0,Number(previousBody?.scrollTop)||0):0;layer.className='goalSheetLayer temptationFlowLayer';const cta=d.step===4?'Opprett mål':'Neste';layer.innerHTML=`<section class="temptationShell goalFlowShell" data-flow-step="${d.step}" role="dialog" aria-modal="true">${goalHeader()}<form id="goalFlowForm"><main class="temptationBody">${goalStep(s)}</main><footer class="temptationFooter"><button class="goalPrimary" type="${d.step===4?'submit':'button'}" ${d.step<4?'data-goalflow-next':''} ${goalReady()?'':'disabled'}>${cta}</button></footer></form></section>`;const form=layer.querySelector('#goalFlowForm');if(sameStep)restoreFlowScroll(layer.querySelector('.temptationBody'),previousScroll);layer.onclick=goalClick;layer.onchange=goalChange;layer.oninput=e=>{if(e.target.name==='goalManualTitle'||e.target.name==='goalRewardCustom'){syncGoal(form);const next=form.querySelector('[data-goalflow-next]');if(next)next.disabled=!goalReady()}};form.onsubmit=submitGoal;window.FlytEdgeSwipeBack?.bind(layer.querySelector('.goalFlowShell'),{canGoBack:()=>goalDraft?.step>1,onBack:()=>{syncGoal(form);goalDraft.step=Math.max(1,goalDraft.step-1);renderGoalFlow()}})}
function openGoalFlow(){const s=state();if(!s)return;goalDraft={step:1,kind:'',metric:{type:'',target:0,taskId:(s.tasks||[]).find(item=>item.kind==='house')?.id||''},metricMemory:{},title:'',deadline:'',reward:'',rewardCustom:''};renderGoalFlow()}
