  const s=state(),p=partner(s);if(!s)return;const metric=goal?.metric||{...defaultGoalMetric(kind),taskId:(s.tasks||[])[0]?.id||''},reward=goal?.reward||{title:'',cost:metric.target||60},standard=Object.values(core().REWARD_LIBRARY).flat().includes(reward.title),editing=!!goal,advanced=metric.type!==defaultGoalMetric(kind).type,title=kind==='challenge'?`Utfordre ${p} ❤️`:kind==='shared'?'Nytt felles mål':'Nytt mål',challenge=metric.type==='points_new'?'points':metric.type==='manual'?'own':'task',pointTarget=['points_week','points_shared','points_new'].includes(metric.type)?Math.max(10,Number(metric.target)||10):Math.max(10,Number(defaultGoalMetric(kind).target)||10),percentTarget=metric.type==='week_percent'?Math.max(10,Math.min(100,Number(metric.target)||75)):75;
