  overlay(`${sheetHead('',title,kind==='challenge'?'Velg én enkel utfordring.':'Et enkelt poengmål er standard.')}<form id="goalEditor" data-kind="${kind}" data-goal-id="${esc(goal?.id||'')}" data-proposal="${proposal?'1':'0'}" data-advanced="${advanced?'1':'0'}" data-original-target="${Math.max(1,Number(metric.target)||1)}"><div class="goalFormCard">${body}</div><button class="goalPrimary goalFormSubmit">${proposal?'Send endringsforslag':editing?'Lagre forslag':kind==='challenge'?'Send utfordring':'Opprett mål'}</button><button type="button" class="goalTextAction" data-goal-close>Avbryt</button></form>`);if(kind==='challenge')$('#goalEditor').elements.challengeType.value=challenge;updateFormVisibility()
