  const rf=e.target.closest('#partnerRewardForm');if(rf){e.preventDefault();const s=state(),title=rf.elements.preset.value==='__custom__'?rf.elements.custom.value.trim():(rf.elements.preset.value||rf.elements.custom.value.trim());if(!title){bridge()?.toast?.('Velg eller skriv en belønning');return}save(core().addPartnerReward(s,rf.dataset.goalId,{title,cost:0,direct:true,model:'earned',secret:!!rf.elements.secret.checked},s.user),'Belønningen er lagt til');$('#goalSheetLayer')?.remove();render();return}
